mapper.delete:
delete from PBC_TARGET_INFO
where ACCOUNT = #{account,jdbcType=VARCHAR}
  and INDENTIFY_MARK = #{indentifyMark,jdbcType=VARCHAR}

mapper.insert:
insert into PBC_TARGET_INFO (ACCOUNT, INDENTIFY_MARK, UUID, PBC_PROD_ID
    HOLDER_NAME, HOLDER_TYPE, HOLD_DATE,
                             CCY, QTY, AMOUNT,
                             CREATE_TIME, UPDATE_TIME, CREATE_USER,
                             CREATE_DEPT, UPDATE_USER, STATUS
)
values (#{account,jdbcType=VARCHAR}, #{indentifyMark,jdbcType=VARCHAR}, #{uuid,jdbcType=VARCHAR}, #{pbcProdId,jdbcType=VARCHAR}
    #{holderName,jdbcType=VARCHAR}, #{holderType,jdbcType=VARCHAR}, #{holdDate,jdbcType=DATE},
        #{ccy,jdbcType=VARCHAR}, #{qty,jdbcType=DECIMAL}, #{amount,jdbcType=DECIMAL},
        #{createTime,jdbcType=TIMESTAMP}, #{updateTime,jdbcType=TIMESTAMP}, #{createUser,jdbcType=VARCHAR},
        #{createDept,jdbcType=VARCHAR}, #{updateUser,jdbcType=VARCHAR}, #{status,jdbcType=VARCHAR}
       )

mapper.select:
SELECT TEMP.* FROM ( SELECT info.UUID AS uuid, info.ACCOUNT AS account, info.INDENTIFY_MARK AS indentifyMark, info.PBC_PROD_ID AS pbcProdId, info.HOLDER_NAME AS holdername, info.HOLDER_TYPE AS holderType, info.HOLD_DATE AS holdDate, info.CCY AS ccy, info.QTY As qty, info.AMOUNT AS amount, info.STATUS AS status, info.UPDATE_TIME AS updateTime FROM PBC_TARGET_INFO info
info.QTY > 0
AND info.ACCOUNT LIKE CONCAT('%',#{account,jdbcType=VARCHAR},'%')
AND info.PBC_PROD_ID = #{pbcProdId,jdbcType=VARCHAR}
AND info.INDENTIFY_MARK LIKE CONCAT('%',#{indentifyMark,jdbcType=VARCHAR},'%')
AND info.HOLDER_NAME = #{holderName,jdbcType=VARCHAR}
AND info.STATUS = #{status,jdbcType=VARCHAR}
AND DATE_FORMAT(info.HOLD_DATE, '%Y-%m-%d') >= #{holdDateStart,jdbcType=VARCHAR}
AND DATE_FORMAT(info.HOLD_DATE, '%Y-%m-%d') <= #{holdDateEnd,jdbcType=VARCHAR}
UNION ALL SELECT err.UUID AS uuid, err.ACCOUNT AS account, err.INDENTIFY_MARK AS indentifyMark, err.PBC_PROD_ID AS pbcProdId, err.HOLDER_NAME AS holdername, err.HOLDER_TYPE AS holderType, err.HOLD_DATE AS holdDate, err.CCY AS ccy, err.QTY AS qty, err.AMOUNT AS amount, err.STATUS AS status, err.UPDATE_TIME AS updateTime FROM PBC_TARGET_INFO_ERRORDATA err
err.ACCOUNT LIKE CONCAT('%',#{account,jdbcType=VARCHAR},'%')
AND err.PBC_PROD_ID = #{pbcProdId,jdbcType=VARCHAR}
AND err.INDENTIFY_MARK LIKE CONCAT('%',#{indentifyMark,jdbcType=VARCHAR},'%')
AND err.HOLDER_NAME = #{holderName,jdbcType=VARCHAR}
AND err.STATUS = #{status,jdbcType=VARCHAR}
AND DATE_FORMAT(err.HOLD_DATE, '%Y-%m-%d') >= #{holdDateStart,jdbcType=VARCHAR}
AND DATE_FORMAT(err.HOLD_DATE, '%Y-%m-%d') <= #{holdDateEnd,jdbcType=VARCHAR}
) TEMP ORDER BY TEMP.updateTime DESC

