SELECT
    COUNT(INDENTIFY_MARK)
FROM
    PBC_TARGET_INFO
WHERE
    INDENTIFY_MARK = #{indentifyMark,jdbcType=VARCHAR}
  AND HOLDER_NAME = #{holderName,jdbcType=VARCHAR}
  AND ACCOUNT = #{account,jdbcType=VARCHAR}
  AND DATE_FORMAT(HOLD_DATE, '%Y-%m-%d') = #{holdDate,jdbcType=VARCHAR}
  AND STATUS != 'D'

SELECT DISTINCT INDENTIFY_MARK AS indentifyMark, HOLDER_TYPE AS holderType, HOLDER_NAME AS holderName FROM CHB_EQU_SUB
HOLDER_TYPE IN ('17','18','19','20','21','22')
AND INDENTIFY_MARK = #{search,jdbcType=VARCHAR}
AND INDENTIFY_MARK = #{initValue,jdbcType=VARCHAR}
LIMIT 1
